// Change keys (0.13): every change has a short key (2–5 upper-case letters, proposal meta `| key: PWR`) that scopes all
// of its ids (PWR-T1, PWR-T1.AC2, PWR-R1, PWR-R1.S1, PWR-BR1, PWR-UC1, PWR-D1). A key is unique forever: active and
// archived changes, legacy keys found in living spec ids (`LACC-R3`), the lock's task keys, every quick file's key
// (0.13.2: `← Change: none | key: QFLT`, generated by makeQuickKey) and the legacy quick key `QT` all take it.
import { promises as fs } from "node:fs";
import { join } from "node:path";
import { paths } from "./project.mjs";
import { readText, readJson } from "./fsutil.mjs";
import { ARCHIVE_DIR_RE, CHANGE_KEY_RE, QUICK_KEY, keyOf, parseId, parseTaskId } from "./specids.mjs";

const ls = async (dir) => (await fs.readdir(dir, { withFileTypes: true }).catch(() => [])).filter((e) => e.isDirectory() && !e.name.startsWith(".")).map((e) => e.name).sort();
const META_KEY = /^> change: \S+.*?\| key: ([A-Za-z0-9]+)/m;
const VOWELS = new Set(["A", "E", "I", "O", "U", "Y"]);
/** Header key of a quick file (`← Change: none | key: QFLT`), or null. */
const QUICK_HEADER_KEY = /^← Change: none \| key: ([A-Z]{2,5})\s*$/m;
export const quickFileKey = (text) => QUICK_HEADER_KEY.exec(String(text || ""))?.[1] ?? null;

/** Key in a proposal text (`> change: … | key: PWR`), or null. */
export const proposalKey = (text) => META_KEY.exec(String(text || ""))?.[1] ?? null;

/**
 * readKeyRegistry(root) -> {byKey: Map key -> [{change|null, archived, source}], byChange: Map changeId -> key}.
 * Sources: proposals (active + archived), ids in living specs (legacy keys), quick files' header keys (source
 * `tasks/<file>`, `quick: true`), the lock's task keys, and the legacy quick key QT (source `quick`).
 */
export async function readKeyRegistry(root) {
  const P = paths(root);
  const byKey = new Map(); const byChange = new Map();
  const add = (key, owner) => {
    if (!key) return;
    if (!byKey.has(key)) byKey.set(key, []);
    const list = byKey.get(key);
    if (!list.some((o) => o.change === owner.change && o.source === owner.source)) list.push(owner);
  };
  add(QUICK_KEY, { change: null, archived: false, source: "quick" });
  for (const d of await ls(P.changes)) {
    const t = await readText(join(P.changes, d, "proposal.md"), null);
    const k = proposalKey(t);
    if (k) { add(k, { change: d, archived: false, source: "proposal" }); byChange.set(d, k); }
  }
  for (const d of await ls(P.archive)) {
    const id = ARCHIVE_DIR_RE.exec(d)?.[2] ?? d;
    const t = await readText(join(P.archive, d, "proposal.md"), null);
    const k = proposalKey(t);
    if (k) { add(k, { change: id, archived: true, source: "proposal" }); if (!byChange.has(id)) byChange.set(id, k); }
  }
  // living spec ids (a legacy key LACC, or the key of an archived change whose proposal went missing)
  for (const cap of await ls(P.specs)) {
    const t = await readText(join(P.specs, cap, "spec.md"), null);
    for (const m of String(t || "").matchAll(/\b([A-Z]{2,5})-(?:R|BR|UC)\d+\b/g)) {
      const k = m[1];
      if (!byKey.has(k)) add(k, { change: null, archived: true, source: `specs/${cap}` });
    }
  }
  for (const n of (await fs.readdir(P.tasks).catch(() => [])).filter((x) => x.endsWith(".md")).sort()) {
    const k = quickFileKey(await readText(join(P.tasks, n), null));
    if (k) add(k, { change: null, archived: false, source: `tasks/${n}`, quick: true });
  }
  const lock = await readJson(P.lock, null);
  for (const T of Object.keys(lock?.tasks || {})) { const p = parseTaskId(T); if (p && !byKey.has(p.key)) add(p.key, { change: lock.tasks[T]?.change ?? null, archived: !!lock.tasks[T]?.archivedAt, source: "lock" }); }
  return { byKey, byChange };
}

/** Owners of `key` other than `changeId` ([] when free for it). */
export function keyOwners(reg, key, changeId = null) {
  return (reg.byKey.get(key) || []).filter((o) => !(changeId && o.change === changeId));
}

/** Who holds a key, in words: "change feat-x", "the quick file tasks/quick-a.md", "the legacy quick tasks (QT)", … */
export function describeOwner(o) {
  if (o.source === "quick") return "the legacy quick tasks (QT, reserved)";
  if (o.quick) return `the quick file ${o.source}`;
  return o.change ? `${o.archived ? "archived " : ""}change ${o.change}` : `legacy ids in ${o.source}`;
}

/** True once the project uses 0.13 keys: a proposal or quick file has a key, or `migrate --ids` wrote the id map.
 *  A keyless project (no key anywhere) still reads `QT-T<n>` quick ids as current. */
export async function isKeyedProject(root, reg = null) {
  reg ||= await readKeyRegistry(root);
  for (const owners of reg.byKey.values()) if (owners.some((o) => o.source === "proposal" || o.quick)) return true;
  return !!(await readIdMap(root));
}

/** checkKey(reg, key, changeId) -> null when ok, else {code, message}. */
export function checkKey(reg, key, changeId = null) {
  if (!CHANGE_KEY_RE.test(String(key || ""))) return { code: "CHANGE_KEY_BAD", message: `change key "${key}" must be 2–5 upper-case letters (A–Z)` };
  const others = keyOwners(reg, key, changeId);
  if (others.length) {
    const o = others[0];
    return { code: "CHANGE_KEY_TAKEN", message: `key ${key} is taken by ${describeOwner(o)}` };
  }
  return null;
}

const letters = (s) => String(s || "").toUpperCase().replace(/[^A-Z]/g, "");
/** Letter of each change type; an unknown type gives its own first letter. */
export const TYPE_LETTERS = { feat: "F", fix: "X", refactor: "R", perf: "P", docs: "D", test: "T", chore: "C", quick: "Q" };
const consonants = (w) => [...w.slice(1)].filter((c) => !VOWELS.has(c)).join("");
/** 3 letters from words: initials of the first 3 (3+ words); initial + next consonant + 2nd initial (2 words);
 *  initial + 2 consonants (1 word). Short words are padded with their own letters. */
export function initials(words) {
  const ws = words.map(letters).filter(Boolean);
  if (!ws.length) return "";
  if (ws.length >= 3) return ws.slice(0, 3).map((w) => w[0]).join("");
  const fill = (w, n) => (w[0] + consonants(w) + w.slice(1)).slice(0, n);
  if (ws.length === 2) return fill(ws[0], 2) + ws[1][0];
  return fill(ws[0], 3);
}

/**
 * keyCandidates(changeId) -> [base key]: the type letter + 3 initials of the id's words after the type prefix
 * (`feat-billing-exec-settle` → `FBES`, `fix-login-page` → `XLGP`). An id without a type prefix gives its initials only.
 * `title` is accepted for compatibility and ignored. Collisions are resolved by suggestKey (a 5th letter).
 */
export function keyCandidates(changeId, _title = null) {
  const parts = String(changeId || "").toLowerCase().split("-").filter(Boolean);
  if (!parts.length) return ["CH"];
  const rest = parts.length >= 2 ? parts.slice(1) : parts;
  const head = parts.length >= 2 ? (TYPE_LETTERS[parts[0]] ?? letters(parts[0])[0] ?? "") : "";
  let k = (head + initials(rest)).slice(0, 4);
  if (k.length < 2) k = (k + "X").slice(0, 2);
  return [k];
}

/** suggestKey(changeId, title, taken:Set|Map) -> a free key (deterministic). */
export function suggestKey(changeId, title, taken) {
  const has = (k) => (taken instanceof Map ? taken.has(k) : taken?.has?.(k));
  const cands = keyCandidates(changeId, title);
  for (const k of cands) if (CHANGE_KEY_RE.test(k) && !has(k)) return k;
  const base = (cands[0] || "CH").slice(0, 4);
  for (const c of "ABCDEFGHIJKLMNOPQRSTUVWXYZ") if (!has(base + c)) return base + c;
  for (const a of "ABCDEFGHIJKLMNOPQRSTUVWXYZ") for (const b of "ABCDEFGHIJKLMNOPQRSTUVWXYZ") if (!has(base.slice(0, 3) + a + b)) return base.slice(0, 3) + a + b;
  throw new Error(`no free key near ${base}`);
}

/** Legacy key of a capability's living ids of unknown origin: `L` + its old key letters (≤ 5), e.g. ACC -> LACC. */
export function legacyKeyFor(cap, oldKey, taken) {
  const has = (k) => (taken instanceof Map ? taken.has(k) : taken?.has?.(k));
  const base = ("L" + (letters(oldKey) || letters(cap))).slice(0, 5);
  const b = base.length >= 2 ? base : (base + "X").slice(0, 2);
  if (!has(b)) return b;
  for (const c of "ABCDEFGHIJKLMNOPQRSTUVWXYZ") { const k = (b.slice(0, 4) + c); if (!has(k)) return k; }
  for (const a of "ABCDEFGHIJKLMNOPQRSTUVWXYZ") for (const c of "ABCDEFGHIJKLMNOPQRSTUVWXYZ") { const k = b.slice(0, 3) + a + c; if (!has(k)) return k; }
  throw new Error(`no free legacy key for ${cap}`);
}

// ---------------------------------------------------------------- quick-file keys (0.13.2)
const AZ = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
/** Slug of a quick file name or slug: "quick-fix-label-typo.md" -> "fix-label-typo". */
export const quickSlug = (s) => String(s || "").replace(/^.*\//, "").replace(/\.md$/, "").replace(/^quick-/, "");
/** Initials of a quick slug (3 letters, same rule as change keys; the slug's type word counts as a word). */
export function quickSlugLetters(slug) {
  return initials(quickSlug(slug).split(/[^A-Za-z]+/));
}
/** Base quick key for `slug`: `Q` + 3 initials of the slug (`mirror-plain-str` → `QMPS`). `seed` is ignored (compat). */
export const quickKeyCandidate = (slug, _seed = null) => { const k = "Q" + quickSlugLetters(slug); return k.length >= 2 ? k : "QX"; };
/**
 * makeQuickKey(slug, taken:Set|Map) -> a free key for a quick file: `Q` + 3 initials of the slug (`fix-label-typo` →
 * `QFLT`), a 5th letter only when that key is taken; never QT. Deterministic, so a dry run and its apply agree.
 */
export function makeQuickKey(slug, taken, _opts = {}) {
  const has = (k) => k === QUICK_KEY || (taken instanceof Map ? taken.has(k) : taken?.has?.(k));
  const base = quickKeyCandidate(slug);
  if (CHANGE_KEY_RE.test(base) && !has(base)) return base;
  const b4 = (base + "XXX").slice(0, 4);
  if (!has(b4)) return b4;
  for (const c of AZ) if (!has(b4 + c)) return b4 + c;
  for (const a of AZ) for (const c of AZ) if (!has(b4.slice(0, 3) + a + c)) return b4.slice(0, 3) + a + c;
  throw new Error(`no free quick key for ${slug}`);
}
/** `← Change: none` gains `| key: KEY` (a file without the line gets it under its title); no-op when a key is there. */
export function setQuickFileKey(text, key) {
  const t = String(text);
  if (/^← Change: none \| key: /m.test(t)) return t;
  if (/^← Change: none\s*$/m.test(t)) return t.replace(/^← Change: none\s*$/m, `← Change: none | key: ${key}`);
  const m = /^# .*$/m.exec(t);
  if (m) return t.slice(0, m.index + m[0].length) + `\n← Change: none | key: ${key}` + t.slice(m.index + m[0].length);
  return `← Change: none | key: ${key}\n` + t;
}

/** Key of an id-bearing string's owner change via the registry: "PWR-T3" -> "feat-x" (null when unknown). */
export function changeOfKey(reg, key) {
  return (reg.byKey.get(key) || []).find((o) => o.change)?.change ?? null;
}

/** Key of any 0.13 id. */
export { keyOf, parseId };

// ---------------------------------------------------------------- id map (written by migrate --ids)
export const ID_MAP_SCHEMA = "hitl.id-map/1";
export const idMapPath = (root) => join(paths(root).index, "id-map.json");
/** The id map of the last `migrate --ids` ({schema, migratedAt, keys, legacyKeys, ids:{old:new}}), or null. */
export async function readIdMap(root) {
  const m = await readJson(idMapPath(root), null);
  return m && m.schema === ID_MAP_SCHEMA && m.ids && typeof m.ids === "object" ? m : null;
}
/** New id of an old (pre-0.13) id through the map; a decision `D-n` needs its change (`feat-x/D-1`). null when unknown. */
export function mapOldId(map, old, change = null) {
  if (!map) return null;
  return map.ids[old] ?? (change ? map.ids[`${change}/${old}`] : null) ?? null;
}
